    for (int i = 0; i < m; i++) scanf("%s", buff[i]), insert(buff[i]);
    for (int i = 0; i < cnt; i++) {
        stack<char> S;
        int t1 = i;
        while (t1 != 0) {
            S.push(pa[t1].second);
            t1 = pa[t1].first;
        }
        tn = 0;
        while (!S.empty()) {
            tmp[tn++] = S.top();
            S.pop();
        }
        for (int j = 0; j < 4; j++) {
            tmp[tn] = zm[j], tmp[tn + 1] = 0;
            for (int pp = 0; pp <= tn + 1; pp++) {
                int st = find(tmp + pp);
                if (st != -1) {
                    con[i][zm[j] - 'A'] = st;
                    break;
                }
            }
        }
    }    
    mem(dp);
    dp[0][0][0] = 1;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j <= i; j++) {
            for (int pos = 0; pos < cnt; pos++) {
                auto ele = dp[i][j][pos];
                if (ele) {
                    for (int sel = 0; sel < 4; sel++) {
                        int newpos = con[pos][zm[sel] - 'A'];
                        int fg;
                        if (dep[newpos] >= i + 1 - j && isTer[newpos] == 1) fg = i + 1;
                        else fg = j;
                        auto &ele1 = dp[i + 1][fg][newpos];
                        ele1 = (ele1 + ele) % MOD;
                    }
                }
            }
        }
    }
    //for (int i = 0; i < n; i++) {
        //for (int j = 0; j <= i; j++) {
            //for (int pos = 0; pos < cnt; pos++) {
                //printf("(%d %d %d) = %d\n", i, j, pos, dp[i][j][pos]);
            //}
        //}
    //}
    int ans = 0;
    for (int pos = 0; pos < cnt; pos++) {
        ans = (ans + dp[n][n][pos]) % MOD;
    }
    Pn(ans);
    return 0;
}
